 <g data-object="fresh" class="mp-game-object" transform="translate(${fresh.x} ${fresh.y})" opacity="${s.newBag==='fitted'&&!s.headOpen?'0':'1'}"><g transform="scale(1.15)">${bagShape(false)}</g></g>
